function model(p) {
  // Eight data privacy terms in data lifecycle order, each with a plain-English definition, a workplace example,
  // a Lucide icon name and a theme (the lifecycle stage where the term matters most).
  const CARDS = [
    ['PII', 'Identify', 'user-round', 'Personally identifiable information: any detail that can point to one specific person.',
      'A support ticket holds a customer\'s name, email address and account number.'],
    ['Consent', 'Collect', 'hand', 'A clear, freely given yes to one specific use of someone\'s data, which they can withdraw later.',
      'A webinar sign-up form asks a separate yes before adding people to the marketing list.'],
    ['Data minimisation', 'Collect', 'filter', 'Collect and keep only the data you really need for the task, and nothing extra.',
      'The expense form asks for the city you travelled to, not your home address.'],
    ['Purpose limitation', 'Use', 'target', 'Use data only for the reason it was collected, unless people agree to something new.',
      'Emails gathered for order updates are not reused for a sales campaign without asking.'],
    ['De-identification', 'Share', 'venetian-mask', 'Removing or masking the details that link data to a person, so they cannot easily be recognised.',
      'HR shares engagement survey results by department, with names and employee IDs removed.'],
    ['Retention', 'Store', 'archive', 'How long data is kept before it must be deleted, set by a written retention rule.',
      'Applications from unsuccessful candidates are deleted 12 months after the role closes.'],
    ['Right to erasure', 'Delete', 'trash-2', 'A person\'s right to ask an organisation to delete the data it holds about them.',
      'A former customer asks to be forgotten, and the team removes their record from the CRM.'],
    ['Data breach', 'Respond', 'shield-alert', 'Personal data lost, stolen or seen by someone who should not see it, by accident or on purpose.',
      'A laptop holding an unencrypted customer list is left on a train and reported the same day.']
  ];
  const ORDERS = ['Lifecycle order', 'A to Z'], ORDER_TEXT = ['data lifecycle', 'A to Z'];
  const oi = Math.max(0, Math.min(1, Math.round(p.order)));
  const showExamples = Math.round(p.showExamples) === 1;
  const lifecycle = CARDS.map((c, i) => ({ c, step: i + 1 }));
  const list = oi === 1 ? lifecycle.slice().sort((a, b) => a.c[0].localeCompare(b.c[0], 'en', { sensitivity: 'base' })) : lifecycle;
  const per = 3.5, duration = +(list.length * per).toFixed(2);
  const cards = list.map(({ c, step }, i) => ({
    index: i + 1, term: c[0], theme: c[1], stage: c[1], icon: c[2], definition: c[3], example: showExamples ? c[4] : null,
    lifecycleStep: step, start: +(i * per).toFixed(2), end: +((i + 1) * per).toFixed(2)
  }));
  const first = cards[0].term, last = cards[cards.length - 1].term;
  const summary = cards.length + ' terms in ' + ORDER_TEXT[oi] + ' order, from ' + first + ' to ' + last +
    (showExamples ? ', each with a workplace example.' : '; switch examples on to see each term at work.');
  return { cards, order: ORDERS[oi], orderText: ORDER_TEXT[oi], showExamples, exampleCount: cards.filter(c => c.example).length,
    perCard: per, duration, markers: cards.map(c => c.start), summary };
}

checkCode:
function check(p) {
  const m = model(p);
  const TERMS = ['PII', 'Consent', 'Data minimisation', 'Purpose limitation', 'De-identification', 'Retention', 'Right to erasure', 'Data breach'];
  const az = Math.round(p.order) === 1;
  const expected = az ? TERMS.slice().sort((a, b) => a.localeCompare(b, 'en', { sensitivity: 'base' })) : TERMS;
  const got = m.cards.map(c => c.term);
  const onceEach = got.length === TERMS.length && TERMS.every(t => got.filter(g => g === t).length === 1);
  const ordered = got.every((t, i) => t === expected[i]);
  const timesOk = m.cards.every((c, i) => c.start < c.end && c.start >= 0 && c.end <= m.duration + 1e-9 && (i === 0 || c.start > m.cards[i - 1].start)) &&
    m.markers.length === m.cards.length && m.markers.every((t, i) => t === m.cards[i].start);
  return {
    pass: onceEach && ordered && timesOk,
    detail: got.length + ' cards, ' + new Set(got).size + ' distinct terms, ' + (ordered ? 'in' : 'NOT in') + ' ' + m.orderText +
      ' order (' + got[0] + ' first, ' + got[got.length - 1] + ' last); card start times run from ' + m.cards[0].start + ' s to ' +
      m.cards[m.cards.length - 1].start + ' s, ' + (timesOk ? 'increasing and within' : 'NOT all within') + ' the ' + m.duration + ' s playback.'
  };
}
